llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary amine closely related to the query's core, has an absolute oral bioavailability of 34% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline, has an absolute oral bioavailability of 30% in healthy volunteers, supporting F ≥ 20% for the query's dimethoxyisoquinoline-like motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Praziquantel, a tetrahydroisoquinoline lactam, has oral bioavailability of 27.2% in patients, supporting F ≥ 20% for the query's lactam-tetrahydroisoquinoline framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a dimethoxybenzamide with a basic N-methylpiperidine, has absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Levosulpiride, a methoxy-substituted benzamide with a basic pyrrolidine, has absolute oral bioavailability of 23.4%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Alfentanil, a piperidine amide, has oral bioavailability of 45 ± 9% under control conditions, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "One verapamil study reported F = 19.4%, slightly below the threshold, but this is borderline and contradicted by multiple other verapamil studies reporting 22–38%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence from verapamil, noscapine, praziquantel, encainide, levosulpiride, and alfentanil indicates human oral bioavailability values of approximately 23–45%, all at or above the 20% threshold. The query's dimethoxyphenyl, tertiary amine, and lactam-tetrahydroisoquinoline features align with these analogues. Borderline low values are outliers and outweighed, so the prediction is high (F ≥ 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "The query is not identical to any evidence molecule; differences in lactam versus nitrile/benzamide and side-chain length may alter first-pass metabolism and absorption.",
    "Some evidence comes from diseased populations or drug-interaction conditions, limiting quantitative transfer to healthy normal conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

